/// <summary>
/// Extension of <c>SalesPickingListJournalPost</c>
/// </summary>
[ExtensionOf(classstr(SalesPickingListJournalPost))]
public final class METSalesPickingListJournalPost_Extension
{

}

Method.Source:
    /// <summary>
    /// Updates the source line for the current journal line.
    /// </summary>
    protected void updateSourceLine()
    {
        METOrderExtractStatus       metOrderExtractStatus = METOrderExtractStatus::Open;

        next updateSourceLine();

        if (!salesLine.METAllowBackOrders)
        {
            metOrderExtractStatus = METOrderExtractStatus::Extracted;
            ttsbegin;

            SalesUpdateRemain      metSalesUpdateRemain = SalesUpdateRemain::construct();
            metSalesUpdateRemain.updateDeliverRemainder(salesLine,
                                                        EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                                        salesLine.ItemId,
                                                        salesLine.InventDimId,
                                                        wmsOrderTrans.Qty,
                                                        wmsOrderTrans.UnitId(),
                                                        salesLine.SalesUnit,
                                                        NoYes::Yes),
                                                        wmsOrderTrans.Qty, 
                                                        wmsOrderTrans.pdsCWQty);
            ttscommit;
        }
        

        if (salesLine.METAllowBackOrders  &&
            (salesLine.SalesQty == salesLine.type().pickedInTotalSalesUnit()))
        {
            metOrderExtractStatus = METOrderExtractStatus::Extracted;
        }
        ttsbegin;
        METSalesLine metSalesLineOrderLine = METSalesLine::find(salesLine.RecId);
        if (metSalesLineOrderLine)
        {
            metSalesLineOrderLine.OrderExtractStatus = metOrderExtractStatus;
            metSalesLineOrderLine.doUpdate();
        }
        ttscommit;

    }

    /// <summary>
    /// Logic to execute at the end of posting.
    /// </summary>
    protected void endPost()
    {

        next endPost();

        salesTable.metUpdateExtractStatus();
    }
